const items = $input.all();
const dataFaceFormatted = [];
const debugInfo = [];

// Função auxiliar para buscar valor de ação específica
function getActionValue(actions, actionType) {
  if (!actions || !Array.isArray(actions)) return 0;
  const action = actions.find(a => a.action_type === actionType);
  return action ? parseFloat(action.value) || 0 : 0;
}

// Função auxiliar para buscar valor monetário de ação
function getActionMonetaryValue(actionValues, actionType) {
  if (!actionValues || !Array.isArray(actionValues)) return 0;
  const action = actionValues.find(a => a.action_type === actionType);
  return action ? parseFloat(action.value) || 0 : 0;
}

// Função auxiliar para formatar números brasileiros
function formatBR(value) {
  return value.toFixed(2).replace(".", ",");
}

// Função para coletar todos os tipos de ação únicos
function collectUniqueActionTypes(items) {
  const actionTypes = new Set();
  const actionValueTypes = new Set();

  items.forEach(item => {
    if (item.json.actions) {
      item.json.actions.forEach(action => {
        actionTypes.add(action.action_type);
      });
    }
    if (item.json.action_values) {
      item.json.action_values.forEach(action => {
        actionValueTypes.add(action.action_type);
      });
    }
  });

  return {
    actions: Array.from(actionTypes).sort(),
    actionValues: Array.from(actionValueTypes).sort()
  };
}

// Coletar todos os tipos de ação disponíveis
const availableActions = collectUniqueActionTypes(items);

// Adicionar informação de debug no início
debugInfo.push({
  info: "=== TIPOS DE AÇÃO DISPONÍVEIS ===",
  actions_encontradas: availableActions.actions.join(", ") || "Nenhuma ação encontrada",
  action_values_encontrados: availableActions.actionValues.join(", ") || "Nenhum valor de ação encontrado"
});

items.forEach(item => {
  const data = item.json;

  // Valores básicos
  const sp = parseFloat(data.spend || 0);
  const impressions = parseInt(data.impressions || 0);
  const reach = parseInt(data.reach || 0);
  const clicks = parseInt(data.clicks || 0);

  // Buscar ações específicas
  const actions = data.actions || [];
  const actionValues = data.action_values || [];

  // Lista expandida de ações possíveis

  // Mensagens - todos os tipos possíveis
  const mensagens = getActionValue(actions, 'onsite_conversion.messaging_conversation_started_7d') ||
                    getActionValue(actions, 'onsite_conversion.messaging_conversation_started') ||
                    getActionValue(actions, 'messaging_conversation_started_7d') ||
                    getActionValue(actions, 'messaging_conversation_started');

  const mensagensFirst = getActionValue(actions, 'onsite_conversion.messaging_first_reply') ||
                         getActionValue(actions, 'messaging_first_reply');

  // Cliques - todos os tipos
  const linkClicks = getActionValue(actions, 'link_click') ||
                     getActionValue(actions, 'website_clicks');
  const outboundClicks = getActionValue(actions, 'outbound_click');

  // Conversões de E-commerce - incluindo variações
  const purchases = getActionValue(actions, 'offsite_conversion.fb_pixel_purchase') ||
                    getActionValue(actions, 'purchase') ||
                    getActionValue(actions, 'omni_purchase') ||
                    getActionValue(actions, 'fb_pixel_purchase');

  const purchaseValue = getActionMonetaryValue(actionValues, 'offsite_conversion.fb_pixel_purchase') ||
                        getActionMonetaryValue(actionValues, 'purchase') ||
                        getActionMonetaryValue(actionValues, 'omni_purchase') ||
                        getActionMonetaryValue(actionValues, 'fb_pixel_purchase');

  const addToCart = getActionValue(actions, 'offsite_conversion.fb_pixel_add_to_cart') ||
                    getActionValue(actions, 'add_to_cart') ||
                    getActionValue(actions, 'fb_pixel_add_to_cart');

  const initiateCheckout = getActionValue(actions, 'offsite_conversion.fb_pixel_initiate_checkout') ||
                           getActionValue(actions, 'initiate_checkout') ||
                           getActionValue(actions, 'fb_pixel_initiate_checkout');

  const viewContent = getActionValue(actions, 'offsite_conversion.fb_pixel_view_content') ||
                      getActionValue(actions, 'view_content') ||
                      getActionValue(actions, 'fb_pixel_view_content');

  // Leads - incluindo formulários instantâneos
  const leads = getActionValue(actions, 'offsite_conversion.fb_pixel_lead') ||
                getActionValue(actions, 'lead') ||
                getActionValue(actions, 'fb_pixel_lead') ||
                getActionValue(actions, 'leadgen_grouped') ||
                getActionValue(actions, 'onsite_conversion.lead_grouped');

  const leadValue = getActionMonetaryValue(actionValues, 'offsite_conversion.fb_pixel_lead') ||
                    getActionMonetaryValue(actionValues, 'lead') ||
                    getActionMonetaryValue(actionValues, 'fb_pixel_lead');

  const completeRegistration = getActionValue(actions, 'offsite_conversion.fb_pixel_complete_registration') ||
                               getActionValue(actions, 'complete_registration') ||
                               getActionValue(actions, 'fb_pixel_complete_registration');

  // Engajamento - expandido
  const postEngagement = getActionValue(actions, 'post_engagement') ||
                         getActionValue(actions, 'page_engagement');
  const pageEngagement = getActionValue(actions, 'page_engagement');
  const postReactions = getActionValue(actions, 'post_reaction') ||
                        getActionValue(actions, 'reaction');
  const postComments = getActionValue(actions, 'comment') ||
                       getActionValue(actions, 'comments');
  const postShares = getActionValue(actions, 'post') ||
                     getActionValue(actions, 'shares');
  const postSaves = getActionValue(actions, 'post_saved') ||
                    getActionValue(actions, 'saved');

  // Vídeo - expandido
  const videoViews = getActionValue(actions, 'video_view') ||
                     getActionValue(actions, 'video_views');
  const video3SecViews = getActionValue(actions, 'video_continuous_2_sec_watched_actions');
  const videoThruPlay = getActionValue(actions, 'video_thruplay_watched_actions');

  // App
  const appInstalls = getActionValue(actions, 'app_install') ||
                      getActionValue(actions, 'mobile_app_install');
  const appUses = getActionValue(actions, 'app_use') ||
                  getActionValue(actions, 'app_custom_event');

  // Landing Page Views - incluindo variações
  const landingPageViews = getActionValue(actions, 'landing_page_view') ||
                           getActionValue(actions, 'offsite_conversion.fb_pixel_view_content') ||
                           getActionValue(actions, 'link_click');

  // Cálculos de métricas
  const ctr = impressions > 0 ? (clicks / impressions * 100) : 0;
  const cpc = clicks > 0 ? sp / clicks : 0;
  const cpm = impressions > 0 ? sp / (impressions / 1000) : 0;
  const frequencia = reach > 0 ? impressions / reach : 0;

  // Custos específicos
  const custoPorMensagem = mensagens > 0 ? sp / mensagens : 0;
  const custoPorLead = leads > 0 ? sp / leads : 0;
  const custoPorCompra = purchases > 0 ? sp / purchases : 0;
  const custoPorVideoView = videoViews > 0 ? sp / videoViews : 0;
  const cplv = landingPageViews > 0 ? sp / landingPageViews : 0;

  // ROAS (Return on Ad Spend)
  const roas = sp > 0 && purchaseValue > 0 ? purchaseValue / sp : 0;

  // Taxas de conversão
  const taxaConversao = clicks > 0 && purchases > 0 ? (purchases / clicks * 100) : 0;
  const taxaLeads = clicks > 0 && leads > 0 ? (leads / clicks * 100) : 0;
  const taxaMensagens = clicks > 0 && mensagens > 0 ? (mensagens / clicks * 100) : 0;

  // Funil de conversão (E-commerce)
  const viewToCart = viewContent > 0 ? (addToCart / viewContent * 100) : 0;
  const cartToCheckout = addToCart > 0 ? (initiateCheckout / addToCart * 100) : 0;
  const checkoutToPurchase = initiateCheckout > 0 ? (purchases / initiateCheckout * 100) : 0;

  // Taxa de engajamento
  const taxaEngajamento = reach > 0 ? (postEngagement / reach * 100) : 0;

  // Métricas de vídeo
  const video25 = getActionValue(data.video_p25_watched_actions || [], 'video_view');
  const video50 = getActionValue(data.video_p50_watched_actions || [], 'video_view');
  const video75 = getActionValue(data.video_p75_watched_actions || [], 'video_view');
  const video100 = getActionValue(data.video_p100_watched_actions || [], 'video_view');
  const videoRetention = videoViews > 0 ? (video100 / videoViews * 100) : 0;

  // Traduzir valores
  const traduzirRanking = (ranking) => {
    if (!ranking || ranking === 'UNKNOWN') return 'Não disponível';
    switch(ranking.toLowerCase()) {
      case 'above_average': return 'Acima da média';
      case 'average': return 'Na média';
      case 'below_average': return 'Abaixo da média';
      case 'below_average_10': return 'Muito abaixo da média';
      case 'below_average_20': return 'Extremamente abaixo';
      case 'below_average_35': return 'Crítico';
      default: return ranking;
    }
  };

  const traduzirGenero = (gender) => {
    if (!gender || gender === 'unknown') return 'Todos';
    switch(gender.toLowerCase()) {
      case 'male': return 'Masculino';
      case 'female': return 'Feminino';
      default: return gender;
    }
  };

  const traduzirDispositivo = (device) => {
    if (!device || device === 'unknown') return 'Todos';
    switch(device.toLowerCase()) {
      case 'mobile': return 'Celular';
      case 'desktop': return 'Computador';
      case 'tablet': return 'Tablet';
      default: return device;
    }
  };

  const traduzirPlataforma = (platform) => {
    if (!platform || platform === 'unknown') return 'Todas';
    switch(platform.toLowerCase()) {
      case 'facebook': return 'Facebook';
      case 'instagram': return 'Instagram';
      case 'audience_network': return 'Rede de Audiência';
      case 'messenger': return 'Messenger';
      default: return platform;
    }
  };

  // Detectar tipo de campanha baseado no nome e métricas
  let tipoCampanha = "Não identificado";
  const nomeCampanha = data.campaign_name.toLowerCase();

  if (nomeCampanha.includes("tráfego") || nomeCampanha.includes("trafego")) {
    tipoCampanha = "Tráfego";
  } else if (nomeCampanha.includes("cad") || nomeCampanha.includes("lead")) {
    tipoCampanha = "Geração de Leads";
  } else if (nomeCampanha.includes("venda") || nomeCampanha.includes("conversão")) {
    tipoCampanha = "Conversão/Vendas";
  } else if (nomeCampanha.includes("engajamento")) {
    tipoCampanha = "Engajamento";
  } else if (nomeCampanha.includes("alcance") || nomeCampanha.includes("branding")) {
    tipoCampanha = "Alcance/Branding";
  }

  // Adicionar informações de debug para cada campanha
  const actionsPresent = actions.map(a => `${a.action_type}: ${a.value}`).join(", ");
  const actionValuesPresent = actionValues.map(a => `${a.action_type}: ${a.value}`).join(", ");

  // Adiciona os dados formatados
  dataFaceFormatted.push({
    // Identificação
    data: data.date_start,
    campanha: data.campaign_name,
    tipo_campanha_detectado: tipoCampanha,
    conjunto_anuncios: data.adset_name || "N/A",
    anuncio: data.ad_name || "N/A",

    // Investimento e Performance Básica
    gasto: formatBR(sp),
    impressoes: impressions.toLocaleString('pt-BR'),
    alcance: reach.toLocaleString('pt-BR'),
    frequencia: formatBR(frequencia),
    cliques: clicks.toLocaleString('pt-BR'),
    taxa_cliques: formatBR(ctr) + '%',
    custo_por_clique: formatBR(cpc),
    custo_mil_impressoes: formatBR(cpm),

    // Mensagens/WhatsApp
    mensagens_iniciadas: mensagens,
    custo_por_mensagem: formatBR(custoPorMensagem),
    taxa_mensagens: formatBR(taxaMensagens) + '%',
    primeira_resposta: mensagensFirst,

    // Conversões e Vendas
    compras: purchases,
    valor_compras: formatBR(purchaseValue),
    custo_por_compra: formatBR(custoPorCompra),
    taxa_conversao: formatBR(taxaConversao) + '%',
    retorno_investimento: formatBR(roas),

    // Leads
    leads: leads,
    custo_por_lead: formatBR(custoPorLead),
    taxa_leads: formatBR(taxaLeads) + '%',
    registros_completos: completeRegistration,

    // Funil de E-commerce
    visualizacoes_conteudo: viewContent,
    adicoes_carrinho: addToCart,
    checkouts_iniciados: initiateCheckout,
    taxa_visualizacao_carrinho: formatBR(viewToCart) + '%',
    taxa_carrinho_checkout: formatBR(cartToCheckout) + '%',
    taxa_checkout_compra: formatBR(checkoutToPurchase) + '%',

    // Engajamento
    engajamento_total: postEngagement,
    taxa_engajamento: formatBR(taxaEngajamento) + '%',
    reacoes: postReactions,
    comentarios: postComments,
    compartilhamentos: postShares,
    salvamentos: postSaves,

    // Vídeo (se aplicável)
    visualizacoes_video: videoViews,
    custo_por_visualizacao: formatBR(custoPorVideoView),
    video_25_porcento: video25,
    video_50_porcento: video50,
    video_75_porcento: video75,
    video_completo: video100,
    taxa_retencao_video: formatBR(videoRetention) + '%',

    // Landing Page
    visualizacoes_pagina: landingPageViews,
    custo_por_visualizacao_pagina: formatBR(cplv),

    // App (se aplicável)
    instalacoes_app: appInstalls,
    usos_app: appUses,

    // Rankings de Qualidade
    qualidade_anuncio: traduzirRanking(data.quality_ranking),
    qualidade_engajamento: traduzirRanking(data.engagement_rate_ranking),
    qualidade_conversao: traduzirRanking(data.conversion_rate_ranking),

    // Segmentação
    idade: data.age || 'Todas',
    genero: traduzirGenero(data.gender),
    dispositivo: traduzirDispositivo(data.device_platform),
    plataforma: traduzirPlataforma(data.publisher_platform),
    posicao_anuncio: data.platform_position || 'Todas',

    // Outras informações úteis
    objetivo_campanha: data.objective || 'Não especificado',
    meta_otimizacao: data.optimization_goal || 'Não especificado',

    // Debug - ações presentes
    _debug_acoes_presentes: actionsPresent || "Nenhuma ação",
    _debug_valores_presentes: actionValuesPresent || "Nenhum valor"
  });
});

// Adicionar linha de totais/resumo no final
if (dataFaceFormatted.length > 0) {
  // Calcular totais
  const totalGasto = dataFaceFormatted.reduce((sum, d) => sum + parseFloat(d.gasto.replace(',', '.')), 0);
  const totalImpressoes = dataFaceFormatted.reduce((sum, d) => sum + parseInt(d.impressoes.replace(/\./g, '') || 0), 0);
  const totalAlcance = dataFaceFormatted.reduce((sum, d) => sum + parseInt(d.alcance.replace(/\./g, '') || 0), 0);
  const totalCliques = dataFaceFormatted.reduce((sum, d) => sum + parseInt(d.cliques.replace(/\./g, '') || 0), 0);
  const totalMensagens = dataFaceFormatted.reduce((sum, d) => sum + d.mensagens_iniciadas, 0);
  const totalCompras = dataFaceFormatted.reduce((sum, d) => sum + d.compras, 0);
  const totalValorCompras = dataFaceFormatted.reduce((sum, d) => sum + parseFloat(d.valor_compras.replace(',', '.')), 0);
  const totalLeads = dataFaceFormatted.reduce((sum, d) => sum + d.leads, 0);

  const totals = {
    data: '*** TOTAIS ***',
    campanha: `${[...new Set(dataFaceFormatted.map(d => d.campanha))].length} campanhas`,
    tipo_campanha_detectado: "Resumo Geral",
    conjunto_anuncios: `${[...new Set(dataFaceFormatted.map(d => d.conjunto_anuncios))].length} conjuntos`,
    anuncio: `${dataFaceFormatted.length} anúncios`,

    // Totais
    gasto: formatBR(totalGasto),
    impressoes: totalImpressoes.toLocaleString('pt-BR'),
    alcance: totalAlcance.toLocaleString('pt-BR'),
    cliques: totalCliques.toLocaleString('pt-BR'),
    mensagens_iniciadas: totalMensagens,
    compras: totalCompras,
    valor_compras: formatBR(totalValorCompras),
    leads: totalLeads,

    // Médias e métricas gerais
    taxa_cliques: formatBR(totalImpressoes > 0 ? (totalCliques / totalImpressoes * 100) : 0) + '%',
    custo_por_clique: formatBR(totalCliques > 0 ? totalGasto / totalCliques : 0),
    custo_mil_impressoes: formatBR(totalImpressoes > 0 ? (totalGasto / (totalImpressoes / 1000)) : 0),
    custo_por_mensagem: formatBR(totalMensagens > 0 ? totalGasto / totalMensagens : 0),
    custo_por_compra: formatBR(totalCompras > 0 ? totalGasto / totalCompras : 0),
    custo_por_lead: formatBR(totalLeads > 0 ? totalGasto / totalLeads : 0),
    retorno_investimento: formatBR(totalGasto > 0 ? totalValorCompras / totalGasto : 0),

    // Campos vazios para manter a estrutura
    frequencia: formatBR(totalAlcance > 0 ? totalImpressoes / totalAlcance : 0),
    taxa_conversao: formatBR(totalCliques > 0 ? (totalCompras / totalCliques * 100) : 0) + '%',
    taxa_mensagens: formatBR(totalCliques > 0 ? (totalMensagens / totalCliques * 100) : 0) + '%'
  };

  dataFaceFormatted.push(totals);
}

// Retornar tanto os dados formatados quanto as informações de debug
return [...debugInfo, ...dataFaceFormatted];

